#include <stdio.h>
int main(void){int n,f,r[100],fr[20],last[20],fault=0,t=0;printf("Reference count and frames: ");scanf("%d%d",&n,&f);if(n>100||f>20||n<1||f<1)return 1;for(int j=0;j<f;j++){fr[j]=-1;last[j]=-1;}printf("Reference string: ");for(int i=0;i<n;i++)scanf("%d",&r[i]);for(int i=0;i<n;i++){int k=-1;for(int j=0;j<f;j++)if(fr[j]==r[i])k=j;if(k<0){fault++;k=0;for(int j=0;j<f;j++)if(fr[j]<0){k=j;break;}else if(last[j]<last[k])k=j;fr[k]=r[i];}last[k]=t++;printf("%d: ",r[i]);for(int j=0;j<f;j++)if(fr[j]<0)printf("- ");else printf("%d ",fr[j]);puts(k>=0?"":"");}printf("Page faults = %d\n",fault);return 0;}
